import { describe, it, expect, vi, beforeEach } from 'vitest';
import { enhancePrompt } from './promptService';
import type { PromptEnhanceContext } from './llm-types';

// Mock the api module
vi.mock('./api', () => ({
  api: {
    post: vi.fn(),
  },
}));

import { api } from './api';

describe('PromptService', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('enhancePrompt', () => {
    it('should enhance prompt without context', async () => {
      const mockResponse = {
        enhancedPrompt: 'A professional LinkedIn banner featuring modern design elements',
        originalPrompt: 'modern design'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const result = await enhancePrompt('modern design');

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        expect.objectContaining({
          prompt: 'modern design',
          context: undefined
        })
      );

      expect(result).toEqual({
        enhancedPrompt: 'A professional LinkedIn banner featuring modern design elements',
        originalPrompt: 'modern design'
      });
    });

    it('should enhance prompt with full context', async () => {
      const mockResponse = {
        enhancedPrompt: 'A tech-focused professional LinkedIn banner with minimal aesthetic and blue accent colors',
        originalPrompt: 'tech banner'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const context: PromptEnhanceContext = {
        industry: 'tech',
        style: 'minimal',
        brandColors: ['#1a73e8', '#34a853']
      };

      const result = await enhancePrompt('tech banner', context);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        expect.objectContaining({
          prompt: 'tech banner',
          context: {
            industry: 'tech',
            style: 'minimal',
            brandColors: ['#1a73e8', '#34a853']
          }
        })
      );

      expect(result).toEqual({
        enhancedPrompt: 'A tech-focused professional LinkedIn banner with minimal aesthetic and blue accent colors',
        originalPrompt: 'tech banner'
      });
    });

    it('should enhance prompt with industry context only', async () => {
      const mockResponse = {
        enhancedPrompt: 'A healthcare-focused professional banner design',
        originalPrompt: 'healthcare banner'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const context: PromptEnhanceContext = {
        industry: 'healthcare'
      };

      const result = await enhancePrompt('healthcare banner', context);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        {
          prompt: 'healthcare banner',
          context: { industry: 'healthcare' }
        }
      );

      expect(result.enhancedPrompt).toBe('A healthcare-focused professional banner design');
      expect(result.originalPrompt).toBe('healthcare banner');
    });

    it('should enhance prompt with style context only', async () => {
      const mockResponse = {
        enhancedPrompt: 'A creative and vibrant LinkedIn banner with bold visual elements',
        originalPrompt: 'banner'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const context: PromptEnhanceContext = {
        style: 'creative'
      };

      const result = await enhancePrompt('banner', context);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        {
          prompt: 'banner',
          context: { style: 'creative' }
        }
      );

      expect(result.enhancedPrompt).toBe('A creative and vibrant LinkedIn banner with bold visual elements');
    });

    it('should enhance prompt with brand colors context only', async () => {
      const mockResponse = {
        enhancedPrompt: 'A LinkedIn banner incorporating brand colors red and yellow',
        originalPrompt: 'branded banner'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const context: PromptEnhanceContext = {
        brandColors: ['#ff0000', '#ffff00']
      };

      const result = await enhancePrompt('branded banner', context);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        {
          prompt: 'branded banner',
          context: { brandColors: ['#ff0000', '#ffff00'] }
        }
      );

      expect(result.enhancedPrompt).toBe('A LinkedIn banner incorporating brand colors red and yellow');
    });

    it('should enhance prompt with multiple context fields', async () => {
      const mockResponse = {
        enhancedPrompt: 'A finance-focused professional banner with elegant styling',
        originalPrompt: 'finance design'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const context: PromptEnhanceContext = {
        industry: 'finance',
        style: 'professional'
      };

      const result = await enhancePrompt('finance design', context);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        {
          prompt: 'finance design',
          context: {
            industry: 'finance',
            style: 'professional'
          }
        }
      );

      expect(result).toEqual(mockResponse);
    });

    it('should handle short prompts', async () => {
      const mockResponse = {
        enhancedPrompt: 'A professional LinkedIn banner with abstract geometric patterns in blue tones',
        originalPrompt: 'blue'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const result = await enhancePrompt('blue');

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        expect.objectContaining({
          prompt: 'blue'
        })
      );

      expect(result.originalPrompt).toBe('blue');
      expect(result.enhancedPrompt).toBeTruthy();
    });

    it('should handle long prompts', async () => {
      const longPrompt = 'Create a highly professional LinkedIn banner for a technology company specializing in artificial intelligence and machine learning solutions, featuring modern design elements, clean typography, and a color scheme that conveys innovation and trustworthiness';
      const mockResponse = {
        enhancedPrompt: 'Enhanced: ' + longPrompt,
        originalPrompt: longPrompt
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const result = await enhancePrompt(longPrompt);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        expect.objectContaining({
          prompt: longPrompt
        })
      );

      expect(result.originalPrompt).toBe(longPrompt);
      expect(result.enhancedPrompt).toContain('Enhanced');
    });

    it('should handle empty context object', async () => {
      const mockResponse = {
        enhancedPrompt: 'Enhanced professional banner design',
        originalPrompt: 'banner'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const context: PromptEnhanceContext = {};

      const result = await enhancePrompt('banner', context);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        {
          prompt: 'banner',
          context: {}
        }
      );

      expect(result).toEqual(mockResponse);
    });

    it('should handle API errors', async () => {
      vi.mocked(api.post).mockRejectedValueOnce(new Error('API Error'));

      await expect(
        enhancePrompt('test prompt')
      ).rejects.toThrow('API Error');
    });

    it('should handle network errors', async () => {
      vi.mocked(api.post).mockRejectedValueOnce(new Error('Network timeout'));

      await expect(
        enhancePrompt('test', { industry: 'tech' })
      ).rejects.toThrow('Network timeout');
    });

    it('should preserve original prompt in response', async () => {
      const originalPrompt = 'simple design';
      const mockResponse = {
        enhancedPrompt: 'A sophisticated and elegant LinkedIn banner design',
        originalPrompt: originalPrompt
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const result = await enhancePrompt(originalPrompt);

      expect(result.originalPrompt).toBe(originalPrompt);
      expect(result.enhancedPrompt).not.toBe(originalPrompt);
    });

    it('should verify API endpoint is correct', async () => {
      const mockResponse = {
        enhancedPrompt: 'Enhanced',
        originalPrompt: 'Original'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      await enhancePrompt('test');

      expect(api.post).toHaveBeenCalledTimes(1);
      expect(vi.mocked(api.post).mock.calls[0][0]).toBe('/api/ai/prompt/enhance');
    });

    it('should handle multiple brand colors', async () => {
      const mockResponse = {
        enhancedPrompt: 'Multi-color branded banner',
        originalPrompt: 'brand banner'
      };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const context: PromptEnhanceContext = {
        brandColors: ['#ff0000', '#00ff00', '#0000ff', '#ffff00']
      };

      const result = await enhancePrompt('brand banner', context);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/prompt/enhance',
        expect.objectContaining({
          context: expect.objectContaining({
            brandColors: expect.arrayContaining(['#ff0000', '#00ff00', '#0000ff', '#ffff00'])
          })
        })
      );

      expect(result).toEqual(mockResponse);
    });
  });
});
